1:/**
2: * Develop Ticket and Create PR Action
3: * Handles git operations, branch creation, commit, push, and PR creation after cursor agent development
4: */
5:
6:// Import common helper functions
7:const { extractTicketKey } = require('./common/jiraHelpers.js');
8:const prHelper = require('./common/pullRequest.js');
9:const submoduleHelper = require('./common/submodules.js');
10:const feedbackLoop = require('./common/feedbackLoop.js');
11:var configLoader = require('./configLoader.js');
12:var autoStart = require('./common/autoStart.js');
13:var outputFiles = require('./common/outputFiles.js');
14:const { GIT_CONFIG, STATUSES, LABELS, resolveStatuses } = require('./config.js');
15:var cacheToReleases = require('./cacheToReleases.js');
16:const tokenUsageComment = require('./common/tokenUsageComment.js');
17:const commentMarkup = require('./common/commentMarkup.js');
18:const gitStaging = require('./common/gitStaging.js');
19:
20:// Tracker-agnostic ticket operations (jira / ado / github) — created lazily per action() run.
21:var trackersModule = require('./common/trackers.js');
22:var _trackerCtx = { config: null, customParams: {} };
23:var _trackerInst = null;
24:function initTracker(config, customParams) {
25:    _trackerCtx = { config: config || null, customParams: customParams || {} };
26:    _trackerInst = null;
27:}
28:function getTracker() {
29:    if (!_trackerInst) _trackerInst = trackersModule.createTracker(_trackerCtx.config, _trackerCtx.customParams);
30:    return _trackerInst;
31:}
