33:function hasPrApprovedLabel(ticket) {
34:    var labels = (ticket && ticket.fields && ticket.fields.labels) ? ticket.fields.labels : [];
35:    return labels.indexOf(LABELS.PR_APPROVED) !== -1;
36:}
