38:// Universal working-directory-aware wrapper for cli_execute_command.
39:// When config.workingDir is set (via customParams.targetRepository.workingDir),
40:// all git/shell commands are executed inside that directory.
41:var _workingDir = null;
42:var _scm = null;
43:function runCmd(args) {
44:    if (_workingDir) args.workingDirectory = _workingDir;
45:    return cli_execute_command(args);
46:}
47:
48:/**
49: * Clean command output from script wrapper artifacts
50: * Removes "Script started/done" lines that DMTools CLI adds
51: *
52: * @param {string} output - Raw command output
53: * @returns {string} Cleaned output
54: */
55:function cleanCommandOutput(output) {
56:    return prHelper.cleanCommandOutput(output);
57:}
58:
59:/**
60: * Generate unique branch name with collision detection
61: * Appends _1, _2, _3 etc. if branch already exists locally or remotely
62: */
63:function generateUniqueBranchName(branchPrefix, ticketKey) {
64:    const baseBranchName = branchPrefix + '/' + ticketKey;
65:
66:    // Check if base branch exists locally or remotely
67:    try {
68:        // No blanket fetch (owner rule 2026-10-03): the remote pattern check
69:        // below queries the remote directly via ls-remote.
70:        // Check local branches
71:        const localBranches = runCmd({
72:            command: 'git branch --list "*' + baseBranchName + '*"'
73:        }) || '';
74:
75:        // Check remote branches — direct remote query, no fetch needed.
76:        // gh-912: keep only real `<sha>\trefs/...` ref lines — a
77:        // `warning: redirecting to …` line (central-mode insteadOf origin,
78:        // git ≥ 2.54) must not read as "name already taken" and force a
79:        // bogus _1 suffix onto the first run of every ticket.
80:        const remoteBranches = prHelper.remoteRefLines(runCmd({
81:            command: 'git ls-remote --heads origin "' + baseBranchName + '*"'
82:        }) || '');
83:
84:        const allBranches = localBranches + '\n' + remoteBranches;
85:
86:        // If no branches exist with this base name, use it
87:        if (!allBranches.trim() || allBranches.trim() === '\n') {
88:            return baseBranchName;
89:        }
90:
91:        // Try with suffixes _1, _2, _3, etc.
92:        for (let i = 1; i <= 10; i++) {
93:            const candidateName = baseBranchName + '_' + i;
94:            if (allBranches.indexOf(candidateName) === -1) {
95:                return candidateName;
96:            }
97:        }
98:
99:        // Fallback: use timestamp suffix if too many collisions
100:        const timestamp = Date.now();
101:        return baseBranchName + '_' + timestamp;
102:
103:    } catch (error) {
104:        console.warn('Error checking existing branches, using base name:', error);
105:        return baseBranchName;
106:    }
107:}
108:
109:/**
110: * Configure git author for AI Teammate commits
111: *
112: * @returns {boolean} True if successful
113: */
114:function configureGitAuthor(config) {
115:    try {
116:        runCmd({
117:            command: 'git config user.name "' + config.git.authorName + '"'
118:        });
119:
120:        runCmd({
121:            command: 'git config user.email "' + config.git.authorEmail + '"'
122:        });
123:
124:        console.log('✅ Configured git author as AI Teammate');
125:        return true;
126:
127:    } catch (error) {
128:        console.error('Failed to configure git author:', error);
129:        return false;
130:    }
131:}
132:
133:/**
134: * Push already-committed changes to remote (used when CLI agent committed its own work).
135: */
136:function performPushOnly(branchName, baseBranch) {
137:    console.log('Pushing pre-committed changes to remote...');
138:    var syncResult = prHelper.syncBranchWithBase({
139:        branchName: branchName,
140:        baseBranch: baseBranch || 'main',
141:        workingDir: _workingDir,
142:        runCommand: function (command, workingDir) {
143:            var args = { command: command };
144:            if (workingDir) args.workingDirectory = workingDir;
145:            return cli_execute_command(args);
146:        }
147:    });
148:    if (!syncResult.success) {
149:        return { success: false, isMergeSyncFailure: true, error: syncResult.error };
150:    }
151:
152:    var pushOutput = '';
153:    var pushThrewException = false;
154:    try {
155:        pushOutput = runCmd({ command: 'git push -u origin ' + branchName }) || '';
156:    } catch (pushErr) {
157:        pushOutput = String(pushErr);
158:        pushThrewException = true;
159:    }
160:
161:    var pushFailed = pushThrewException ||
162:        pushOutput.indexOf('remote rejected') !== -1 ||
163:        pushOutput.indexOf('GH013') !== -1 ||
164:        pushOutput.indexOf('error: failed to push') !== -1 ||
165:        pushOutput.indexOf('push declined') !== -1 ||
166:        pushOutput.indexOf('non-fast-forward') !== -1 ||
167:        pushOutput.indexOf('rejected') !== -1;
168:
169:    if (pushFailed) {
170:        // Try force push (branch may have diverged from a previous interrupted run)
171:        console.log('Push rejected — retrying with --force...');
172:        var forceOutput = '';
173:        try {
174:            forceOutput = runCmd({ command: 'git push -u origin ' + branchName + ' --force' }) || '';
175:        } catch (forceErr) {
176:            forceOutput = String(forceErr);
177:        }
178:        var forceFailed = forceOutput.indexOf('remote rejected') !== -1 ||
179:            forceOutput.indexOf('GH013') !== -1 ||
180:            forceOutput.indexOf('error: failed to push') !== -1 ||
181:            forceOutput.indexOf('push declined') !== -1;
182:        if (forceFailed) {
183:            return { success: false, isPushFailure: true, error: 'Push still rejected after force: ' + forceOutput.substring(0, 300) };
184:        }
185:    }
186:
187:    var lsRemote = runCmd({ command: 'git ls-remote --heads origin ' + branchName }) || '';
188:    if (lsRemote.indexOf('refs/heads/' + branchName) === -1) {
189:        return { success: false, isPushFailure: true, error: 'Branch not found on remote after push' };
190:    }
191:
192:    console.log('✅ Push-only git operations completed successfully');
193:    return { success: true, branchName: branchName };
194:}
