196:/**
197: * Stage changes, commit, and push on current branch
198: *
199: * @param {string} branchName - Current branch name (already checked out by preCliJSAction)
200: * @param {string} commitMessage - Commit message
201: * @param {string} baseBranch - Base branch used to detect existing local/remote commits
202: * @param {Object} config - Resolved project config, including optional managed submodules
203: * @param {Object} customParams - Runtime custom params, including optional managed submodules
204: * @param {string} ticketKey - Ticket key used for managed submodule commit messages
205: * @returns {Object} Result with success status and branch name
206: */
207:function performGitOperations(branchName, commitMessage, baseBranch, config, customParams, ticketKey) {
208:    try {
209:        submoduleHelper.pushManagedSubmodules({
210:            run: function (command) {
211:                return runCmd({ command: command });
212:            },
213:            cleanOutput: cleanCommandOutput,
214:            config: config,
215:            customParams: customParams,
216:            ticketKey: ticketKey
217:        });
218:
219:        try {
220:            // gh-628: machine-local runtime logs live inside the committed
221:            // .dmtools/ directory — untrack them on already-poisoned
222:            // branches; the staging pathspec below keeps them out going
223:            // forward. Shared canonical list: js/common/gitStaging.js.
224:            gitStaging.untrackRuntimeArtifacts(function (command) { return runCmd({ command: command }); });
225:        } catch (cleanupErr) {
226:            console.warn('Could not remove tracked Copilot session cache before staging:', cleanupErr);
227:        }
228:
229:        // Stage all changes
230:        // `:!factory-kit` — the factory workflow's kit step materializes a
231:        // NESTED git repo at $GITHUB_WORKSPACE/factory-kit (git init + one
232:        // sparse checkout); staging a gitlink that "does not have a commit
233:        // checked out" fails the whole add with exit 128 and kills the PR
234:        // post-action (live gh-1000, 2026-10-03: dev leg green, "Git
235:        // operations failed" — no PR). Excluded like copilot-sessions.
236:        // `:!.dmtools/...` runtime logs (gh-628) — excluded by pathspec
237:        // because they live next to COMMITTED .dmtools/ files.
238:        // gh-683 (live fa run 37153405587): `git add` trips its
239:        // ignored-pathspec guard when an exclusion pathspec NAMES a path
240:        // that is gitignored and exists untracked — buildStagingPathspecs
241:        // probes each artifact with `git check-ignore` (via runCmd) and
242:        // omits the exclusion for paths git already ignores, so this add
243:        // can never hit the "paths are ignored" guard.
244:        // gh-1164 (live fa runs 37153882406 + 37220167230): `factory-kit`
245:        // goes through the same probe — a static `:!factory-kit` exclusion
246:        // trips the very same guard when the kit is materialized AND
247:        // gitignored, silently starving the leg's commits.
248:        // gh-729: this line is the LAST visible step before the silent 23s
249:        // in live fa gh-1197 (run 37234028759) — the tail must log every
250:        // step so a stall/kill here is diagnosable from the job log.
251:        console.log('Staging working tree (check-ignore probe-filtered exclusions)...');
252:        runCmd({
253:            command: 'git add . -- ' + gitStaging.buildStagingPathspecs(runCmd, ['factory-kit'])
254:        });
255:
256:        // Check if there are changes to commit
257:        const statusOutput = prHelper.readStagedDiffStat(function (command) {
258:            return runCmd({ command: command });
259:        }, _workingDir);
260:
261:        if (!statusOutput || !statusOutput.trim()) {
262:            // gh-729: name this branch in the log — the live gh-1197 leg went
263:            // quiet between the staging probes and the PR-create call, and
264:            // without step logs that window is indistinguishable from a
265:            // clean "nothing to do".
266:            console.log('Nothing staged — checking whether the agent already committed or pushed its work...');
267:            // No uncommitted changes — but check if the agent already committed its work
268:            // (the CLI agent sometimes commits itself before postJSAction runs)
269:            var originRef = baseBranch ? 'origin/' + baseBranch : 'origin/main';
270:            var aheadOutput = '';
271:            try {
272:                aheadOutput = cleanCommandOutput(runCmd({ command: 'git rev-list --count ' + originRef + '..HEAD' }) || '');
273:            } catch (e) {
274:                console.warn('Could not check commits ahead of ' + originRef + ':', e);
275:            }
276:            var commitsAhead = parseInt(aheadOutput, 10) || 0;
277:            if (commitsAhead > 0) {
278:                console.log('No uncommitted changes, but branch is ' + commitsAhead + ' commit(s) ahead of ' + originRef + ' — agent already committed. Skipping commit step.');
279:                // Jump straight to push after syncing with the latest base branch.
280:                return performPushOnly(branchName, baseBranch);
281:            }
282:
283:            // Check if the remote branch already has commits not yet in origin/main
284:            // (e.g. agent pushed in a previous run but was interrupted before PR creation)
285:            var remoteAheadOutput = '';
286:            try {
287:                // Fetch remote refs so origin/<branchName> is up to date
288:                try { runCmd({ command: prHelper.buildOriginFetchCommand(branchName) }); } catch (e) { }
289:                remoteAheadOutput = cleanCommandOutput(runCmd({ command: 'git rev-list --count ' + originRef + '..origin/' + branchName }) || '');
290:            } catch (e) {
291:                console.warn('Could not check remote branch commits:', e);
292:            }
293:            var remoteCommitsAhead = parseInt(remoteAheadOutput, 10) || 0;
294:            if (remoteCommitsAhead > 0) {
295:                console.log('Remote branch origin/' + branchName + ' is ' + remoteCommitsAhead + ' commit(s) ahead of ' + originRef + ' — branch already pushed. Skipping push, proceeding to PR creation.');
296:                // No push needed — return success so the caller proceeds to PR creation
297:                return { success: true, branchName: branchName };
298:            }
299:
300:            console.warn('No changes to commit');
301:            return {
302:                success: false,
303:                error: 'No changes were made by the development process'
304:            };
305:        }
306:
307:        // Commit changes — sanitize message to avoid shell metacharacter rejection
308:        var safeMessage = commitMessage
309:            .replace(/"/g, '\\"')
310:            .replace(/[><|;`$\r\n]/g, ' ')
311:            .replace(/\s+/g, ' ')
312:            .trim();
313:        console.log('Committing changes...');
314:        runCmd({
315:            command: 'git commit -m "' + safeMessage + '"'
316:        });
317:
318:        var syncResult = prHelper.syncBranchWithBase({
319:            branchName: branchName,
320:            baseBranch: baseBranch || 'main',
321:            workingDir: _workingDir,
322:            runCommand: function (command, workingDir) {
323:                var args = { command: command };
324:                if (workingDir) args.workingDirectory = workingDir;
325:                return cli_execute_command(args);
326:            }
327:        });
328:        if (!syncResult.success) {
329:            return {
330:                success: false,
331:                isMergeSyncFailure: true,
332:                error: syncResult.error
333:            };
334:        }
335:
336:        // Push to remote
337:        console.log('Pushing to remote...');
338:        var pushOutput = '';
339:        var pushThrewException = false;
340:        try {
341:            pushOutput = runCmd({
342:                command: 'git push -u origin ' + branchName
343:            }) || '';
344:        } catch (pushErr) {
345:            // git push exits with non-zero (e.g. non-fast-forward) — cli_execute_command throws
346:            pushOutput = String(pushErr);
347:            pushThrewException = true;
348:        }
349:
350:        // Check output text for soft-rejected pushes (exit 0 but error text) AND
351:        // exception messages (exit non-zero) — covers both code paths.
352:        const pushFailed = pushThrewException ||
353:            pushOutput.indexOf('remote rejected') !== -1 ||
354:            pushOutput.indexOf('GH013') !== -1 ||
355:            pushOutput.indexOf('error: failed to push') !== -1 ||
356:            pushOutput.indexOf('push declined') !== -1 ||
357:            pushOutput.indexOf('non-fast-forward') !== -1 ||
358:            pushOutput.indexOf('rejected') !== -1;
359:
360:        if (pushFailed) {
361:            return {
362:                success: false,
363:                isPushFailure: true,
364:                error: 'Push was rejected by remote: ' + pushOutput.substring(0, 500)
365:            };
366:        }
367:
368:        // Verify branch is actually present on remote
369:        console.log('Verifying branch is pushed to remote...');
370:        const lsRemoteOutput = runCmd({
371:            command: 'git ls-remote --heads origin ' + branchName
372:        }) || '';
373:
374:        // ls-remote stdout contains refs/heads/<branch> when the branch exists
375:        if (lsRemoteOutput.indexOf('refs/heads/' + branchName) === -1) {
376:            return {
377:                success: false,
378:                isPushFailure: true,
379:                error: 'Branch was not found on remote after push'
380:            };
381:        }
382:
383:        console.log('✅ Git operations completed successfully');
384:        return {
385:            success: true,
386:            branchName: branchName
387:        };
388:
389:    } catch (error) {
390:        console.error('Git operations failed:', error);
391:        return {
392:            success: false,
393:            error: error.toString()
394:        };
395:    }
396:}
