514:/**
515: * Detects CLI/environment failures that a retry can never fix — e.g. the configured
516: * AI_AGENT_PROVIDER binary (cursor-agent, kimi, claude, ...) is missing from the
517: * runner's PATH, or AI_AGENT_PROVIDER names an unknown provider. run-agent.sh surfaces
518: * these as "Command failed (exit code 127)" (127 = shell "command not found"), unlike
519: * transient failures (rate limits, timeouts = exit code 124) that a resume/retry can
520: * plausibly resolve. Silently resetting the ticket for retry on this class of error
521: * just loops forever, since the missing tool never appears on its own.
522: *
523: * `cliReportedFatalError` is Teammate's own authoritative signal (params.currentCliHasFatalError,
524: * set whenever cliResult.hasFatalError() is true — covers provider/network errors such as HTTP
525: * 5xx that never match the regexes below) and always wins over the text heuristics: relying on
526: * text-sniffing alone let those failures fall through as a plain "interrupted, will retry",
527: * masking a non-retryable failure as a transient one.
528: */
529:function isFatalCliEnvironmentError(responseText, cliReportedFatalError) {
530:    if (cliReportedFatalError) {
531:        return true;
532:    }
533:    var text = String(responseText || '');
534:    return /exit code 127\)/.test(text) ||
535:        /not found in PATH/i.test(text) ||
536:        /Error: unknown provider/i.test(text);
537:}
538:
539:function postFatalCliEnvironmentErrorToJira(ticketKey, errorMessage) {
540:    try {
541:        const m = commentMarkup.forTicket(ticketKey);
542:        getTracker().postComment(ticketKey, m.h(3, '❌ AI CLI Environment Failure') + '\n\n' +
543:                'The configured AI CLI tool could not run on the runner (e.g. missing binary or misconfigured provider):\n\n' + m.code(errorMessage) + '\n\n' +
544:                'This is an infrastructure/setup problem, not a normal work-item issue — retrying will fail the same way until the runner environment is fixed. The job has been failed explicitly instead of silently looping on retry.');
545:    } catch (e) {
546:        console.error('Failed to post fatal CLI environment error comment:', e);
547:    }
548:}
