550:/**
551: * Posts the fatal-error comment and throws a marked Error so it propagates out of
552: * action() uncaught (see the outer catch below) instead of being swallowed into the
553: * usual "reset for retry" recovery path.
554: */
555:function throwFatalCliEnvironmentError(ticketKey, errorMessage) {
556:    postFatalCliEnvironmentErrorToJira(ticketKey, errorMessage);
557:    var err = new Error('Fatal CLI/environment failure: ' + errorMessage);
558:    err.fatalCliEnvironment = true;
559:    throw err;
560:}
