578:/**
579: * gh-775: recovery gate for a missing/blank outputs/response.md, shared by
580: * both cold-reset sites. Order is fixed by the acceptance criteria:
581: *
582: *   1. Fatal CLI/environment class (missing provider binary, unknown provider,
583: *      fatal provider error) → throwFatalCliEnvironmentError. A resume can
584: *      never fix that class, so the resume never preempts it (AC6).
585: *   2. Otherwise exactly ONE bounded resume attempt re-invokes the provider
586: *      wrapper with the follow-up prompt — "the verification run hung:
587: *      bash_job stop it, note it, write outputs/response.md and finish" — so
588: *      a session that lost time to a hung background child can still land the
589: *      deliverable (AC2). Zero tracker side effects happen before the attempt
590: *      resolves; the caller only reaches its comment/status/wip sequence when
591: *      the deliverable is STILL missing (AC4).
592: *
593: * Returns the re-read response content, or null when the resume is not
594: * applicable / did not land — the caller then continues into its existing
595: * cold-reset path unchanged.
596: */
597:function recoverMissingResponse(ticketKey, customParams, developmentSummary, cliHasFatalError, cliErrorMessage) {
598:    if (isFatalCliEnvironmentError(developmentSummary, cliHasFatalError)) {
599:        console.error('CLI/environment failure detected (e.g. AI CLI binary missing from PATH, or a fatal provider/network error reported by dmtools) — failing the job explicitly instead of resetting for retry.');
600:        throwFatalCliEnvironmentError(ticketKey, cliErrorMessage || developmentSummary);
601:    }
602:    var resume = feedbackLoop.resumeOnceForMissingResponse({
603:        ticketKey: ticketKey,
604:        customParams: customParams
605:    });
606:    if (!resume.attempted) {
607:        console.log('Bounded resume for the missing deliverable not attempted (' + (resume.reason || 'disabled') + ') — continuing to the existing reset path.');
608:        return null;
609:    }
610:    var recovered = readResponseMd(ticketKey);
611:    if (recovered && recovered.trim()) {
612:        console.log('✅ Bounded resume landed outputs/response.md — continuing the normal path (no cold reset).');
613:        return recovered;
614:    }
615:    console.log('Bounded resume did not land outputs/response.md — continuing to the existing reset path.');
616:    return null;
617:}
