679:function labelsToRemove(customParams, metadata) {
680:    var labels = [];
681:    if (customParams && customParams.removeLabel) labels.push(customParams.removeLabel);
682:    if (customParams && Array.isArray(customParams.removeLabels)) {
683:        customParams.removeLabels.forEach(function (label) { labels.push(label); });
684:    }
685:    if (metadata && metadata.contextId) labels.push(metadata.contextId + '_wip');
686:
687:    var seen = {};
688:    return labels.filter(function (label) {
689:        if (!label || seen[label]) return false;
690:        seen[label] = true;
691:        return true;
692:    });
693:}
