26:function trimDiscussionsMarkdown(markdown, maxThreads) {
27:    if (!markdown || maxThreads <= 0) return markdown;
28:    var marker = '\n### Thread ';
29:    var idx = markdown.indexOf(marker);
30:    if (idx === -1) return markdown;
31:    var header = markdown.substring(0, idx);
32:    var rest = markdown.substring(idx + marker.length);
33:    var sections = rest.split(marker);
34:    if (sections.length <= maxThreads) return markdown;
35:    var kept = sections.slice(sections.length - maxThreads);
36:    return header + marker + kept.join(marker);
37:}
