60: * Generate unique branch name with collision detection
61: * Appends _1, _2, _3 etc. if branch already exists locally or remotely
62: */
63:function generateUniqueBranchName(branchPrefix, ticketKey) {
64:    const baseBranchName = branchPrefix + '/' + ticketKey;
65:
66:    // Check if base branch exists locally or remotely
67:    try {
68:        // No blanket fetch (owner rule 2026-10-03): the remote pattern check
69:        // below queries the remote directly via ls-remote.
70:        // Check local branches
71:        const localBranches = runCmd({
72:            command: 'git branch --list "*' + baseBranchName + '*"'
73:        }) || '';
74:
75:        // Check remote branches — direct remote query, no fetch needed.
76:        // gh-912: keep only real `<sha>\trefs/...` ref lines — a
77:        // `warning: redirecting to …` line (central-mode insteadOf origin,
78:        // git ≥ 2.54) must not read as "name already taken" and force a
79:        // bogus _1 suffix onto the first run of every ticket.
80:        const remoteBranches = prHelper.remoteRefLines(runCmd({
81:            command: 'git ls-remote --heads origin "' + baseBranchName + '*"'
82:        }) || '');
83:
84:        const allBranches = localBranches + '\n' + remoteBranches;
85:
86:        // If no branches exist with this base name, use it
87:        if (!allBranches.trim() || allBranches.trim() === '\n') {
88:            return baseBranchName;
89:        }
90:
91:        // Try with suffixes _1, _2, _3, etc.
92:        for (let i = 1; i <= 10; i++) {
93:            const candidateName = baseBranchName + '_' + i;
94:            if (allBranches.indexOf(candidateName) === -1) {
95:                return candidateName;
96:            }
97:        }
98:
99:        // Fallback: use timestamp suffix if too many collisions
100:        const timestamp = Date.now();
101:        return baseBranchName + '_' + timestamp;
102:
103:    } catch (error) {
104:        console.warn('Error checking existing branches, using base name:', error);
105:        return baseBranchName;
106:    }
107:}
