export function expandPaths(args, projectRoot, keep = isSourceFile) {
  const result = new Set();
  for (const arg of args) {
    const p = path.resolve(projectRoot, arg);
    let st;
    try {
      st = statSync(p);
    } catch {
      continue;
    }
    if (st.isDirectory()) {
      for (const f of walkDir(p, keep)) result.add(f);
    } else if (keep(p, st)) {
      result.add(p);
    }
  }
  return [...result].sort();
}

