        var checkoutError = ensureExpectedBranchCheckedOut(ctx.expectedBranch);
        if (checkoutError) {
            resetDevelopmentForRetry(ctx.ticketKey, ctx.statuses, ctx.customParams, ctx.metadata, 'Git Branch Checkout', checkoutError);
