                '   ```\n' +
                '   git rm --cached <filename>\n' +
                '   git commit --amend --no-edit\n' +
                '   ```\n' +
                '3. Do NOT push — just fix the commit history\n'
        });
        console.log('Wrote push error to', errorFilePath);
    } catch (e) {
