function analyze(repoFile, covKey, names) {
  const f=c[covKey];
  if(!f){ console.log(covKey, 'NO COVERAGE KEY'); return; }
  const src=fs.readFileSync(repoFile,'utf8').split('\n');
  function rangeOf(name){ const re=new RegExp('^function '+name+'\\\\(',''); for(let i=0;i<src.length;i++){ if(re.test(src[i])){ let depth=0; for(let j=i;j<src.length;j++){ for(const ch of src[j]){ if(ch==='{')depth++; else if(ch==='}'){depth--; if(depth===0) return [i+1,j+1]; } } } } } return null; }
  function crap(cc,cov){ return cc + cc*cc*Math.pow(1-cov,2); }
  names.forEach(n=>{
    const r=rangeOf(n);
    if(!r){ console.log(n.padEnd(32),'NOT FOUND'); return; }
